import{_ as t,a}from"./chunks/8d519c1009dd357eca1a.DvtShP6b.js";import{_ as l,C as i,o,c as n,j as e,a as s,E as h,a5 as u}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"整合者：为好奇者打造的数字职业道路","description":"","frontmatter":{"title":"整合者：为好奇者打造的数字职业道路","originalTitle":"The Synthesizer: A Digital Career Path For Curious People","date":"2023-12-30","originalUrl":"https://thedankoe.com/letters/the-synthesizer-a-digital-career-path-for-curious-people/","minutes":17,"sourceHash":"c8f18f3ccaed1b165fd9a649fa3cfba6c55e06784dbfaf9321c9be452fdc628b","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-synthesizer-a-digital-career-path-for-curious-people/"}]]},"headers":[],"relativePath":"letters/the-synthesizer-a-digital-career-path-for-curious-people.md","filePath":"letters/the-synthesizer-a-digital-career-path-for-curious-people.md"}'),c={name:"letters/the-synthesizer-a-digital-career-path-for-curious-people.md"};function f(d,p,m,g,b,k){const r=i("ArticleMeta");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"整合者-为好奇者打造的数字职业道路",tabindex:"-1"},[s("整合者：为好奇者打造的数字职业道路 "),e("a",{class:"header-anchor",href:"#整合者-为好奇者打造的数字职业道路","aria-label":'Permalink to "整合者：为好奇者打造的数字职业道路"'},"​")],-1)),h(r),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/CxJZV-NSORU?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>上周，我们的技术创始人兼 Kortex 产品负责人——<a href="https://twitter.com/TheMatthewAo" target="_blank" rel="noreferrer">马修·敖 (Matthew Ao)</a>——顿悟了。</p><p>首先，给那些不知道的人科普一下，马修是个“家庭破坏者”。</p><p>13个月前，乔伊 (Joey) 和我开始打造 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>（前身是 ValueVault）。</p><p>10个月前，我们雇了（1）个开发人员来开发这款第二大脑应用程序。</p><p>但这不只是一款普通的第二大脑应用。而是一款真正有用的。一款能产生实际效果的。一款能让你把知识库转化为有影响力的写作输出，用于内容创作、视频、播客、团队协作、学生项目等等。最终能让我们创造出一种新型社交媒体。</p><p>大多数“第二大脑”应用只不过是美化过的记笔记软件而已。</p><p>到了7月13日，乔伊已经花掉了5万美元——情况进展得并不太顺利。</p><p>我们的每周通话和进度更新既缓慢又无聊。</p><p>我们对这个项目的热情正在迅速消退。</p><p>我们没有取得我们想要的进展。我也不知道我们指望一个开发人员能搞出什么名堂……但我们以前确实没做过这个。如果你了解我，你就会知道我喜欢不管自己懂多少就直接开始动手构建……而且往往结果还他妈的挺不错。</p><p>当时，乔伊正在协助达科塔·罗伯逊 (Dakota Robertson) 开展他的代写训练营。</p><p>我作为嘉宾参加了一次通话，分享我的写作过程。</p><p>在通话快结束时，我提到乔伊和我正在开发一款应用程序。</p><p>马修解除了麦克风静音：“等等，什么样的应用程序？”</p><p>我们简要介绍了一下这款应用，他说他有一些想法，然后我们就转到私信里继续聊了。</p><p>简而言之，他说服了我们把 ValueVault 彻底烧光，从头开始。</p><p>我们拉他入伙成为了创始人。</p><p>快进到现在，我们：</p><ul><li>拥有一支由10名不可思议的开发人员、3名 KortexU 讲师、一个设计团队、一个销售团队，以及拥有受众和杠杆来推动这一切的创始人组成的团队（是的，这时候一人企业早就不存在了（但它仍然可以说是最好的起点））。</li><li>在变现的第一个月就创造了18万美元的收入（这还是在应用还没上线……也没有投资者的情况下……以后再详谈这事儿。我们只是实践了我在商业信件中所讲的内容）。</li><li>建立了 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>，致力于成为互联网上最好的新学校和项目，帮助人们作为整合者、创作者或作家开启数字职业生涯。</li><li>拜访了我们在多伦多的开发团队，并规划了未来。</li><li>计划在1月下旬如期发布应用程序的第0版，专供 Kortex University 内部成员使用，暂不对公众开放。</li><li>除我们自己的出资外，不打算接受任何风险投资或外部投资——我们将坚持我们的理念，利用技术和社交媒体杠杆，实现比99%的初创企业更快的增长。</li></ul><p>这是我们在加拿大举办的首次线下产品演示（针对当时在加拿大的人）。</p><p><img src="'+t+'" alt=""></p><p>哦……而且我正是在 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 里写这篇新闻信的 🙂</p><p>所以，如果你注意到文中大思想的融合，且完全没有写作瓶颈的痕迹，这就是原因。</p><p>好了，回到马修的顿悟：</p><h2 id="好奇心是你在未知领域的指南针" tabindex="-1">好奇心是你在未知领域的指南针 <a class="header-anchor" href="#好奇心是你在未知领域的指南针" aria-label="Permalink to &quot;好奇心是你在未知领域的指南针&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><blockquote><p>做成伟大事业的方法就是探索你的好奇心。因为历史上每一个成就了伟大事业的人，都是那些创造足迹的人，而不是追随别人足迹的人。——马修·敖</p></blockquote><p>马修很实在地提到，这个见解来自保罗·格雷厄姆 (Paul Graham) 关于 <a href="https://paulgraham.com/greatwork.html" target="_blank" rel="noreferrer">如何成就伟大事业 (How To Do Great Work)</a> 的文章。</p><p>显而易见，如果你想要未知的成果，你就必须走一条未知的道路，但人们太容易为了舒适去依附别人的梦想，从而牺牲了自己的梦想。</p><p>好奇心是你在未知领域的指南针。</p><p>好奇心是整合者的必经之路。</p><p>好奇心是这个世界被发现和构建的方式。</p><p>社会创造了已知（且严重过时）的路径，比如上学、找工作，然后65岁退休。</p><p>大脑渴望秩序，于是人们错误地依附于社会为他们创造的秩序。</p><p>大脑渴望秩序，是因为它在要求你去做那些能在无序中创造有序的事情。那就是从好奇心中收集见解并用它来创造——这是你作为人类的优势。其他生物不像我们这样能改变进化的方向。</p><p>随着时间的推移，太多的秩序、确定性和生活在已知之中对你的心理来说变得危险。最终，它会渴望无序。如果你“度假”太久，那就不再是度假了，你会想回家工作。</p><p>这是宇宙的推拉法则。</p><p>万物都像叙事一样，分章节和阶段展开。你的生活、你的想法、你的自我、你的城市、你的社区、你的生意、社会、文化，一直大到宇宙。试图一生都停留在某一个章节，是导致情感动荡的祸根。生活在继续，而你的大脑却试图冻结时间。</p><p>学校和工作有其价值，但在那条已知的路径上走得太久，会让你陷入一种被称为“熵”的平庸且无法逃脱的下行螺旋。</p><p>那些追求好奇心的人正在收集创造力的弹药，以便在他们的生活中不断创造一种进化的秩序。</p><p>熵定律指出，万物都趋向于无序。进化正是如此。我们依附的秩序并不是永久的，比如一份工作，它会随着时间的推移而崩塌。大多数人接受了这一点，在一种悲哀的状态中度过一生，而不是通过创业去推动个人的进化。</p><p>为了作为一名创业者生存下去，你必须继续坚持、迭代和进化。</p><p>查尔斯·达尔文 (Charles Darwin)、埃隆·马斯克 (Elon Musk)、爱因斯坦 (Einstein) 以及其他伟人都追求了他们的好奇心。</p><p><em>他们是朝着未来愿景整合经验的整合者。</em></p><p>他们取得突破，不是因为遵循了死板的课程，而是因为整合了他们在探索好奇心的道路上所发现的一切。</p><p>他们的好奇心引领他们进行了跨学科研究。</p><p>没有人相信他们，因为他们看到了别人没看到的东西。</p><p>他们被那些意识层次低、走着已知路径的人嘲笑——因为这些人既没有，也无法复制源自好奇心的那些信息。</p><p>我在自己的生活中也注意到了这一点。</p><p>当我停止学习商业时，我的商业成果却一飞冲天（不过在追随他人路径之后，我已经对其中的原理有了扎实的掌握）。</p><p>然后，我研究了哲学、形而上学和心理学。</p><p>我能够在这些领域发现相同的原理，但却是站在一个更高的视角，我也因此提升了我的商业成果。</p><p>这种模式识别给我的生活带来了意义，提供了动力的源泉，并让我对所有领域都有了更深的理解（因为它们全都囊括在生活这个大领域之下）。</p><p>几天前，哈姆扎 (Hamza) 在通话中问我，是什么带来了我的成长，我唯一能想到的（且不是你到处都能听到的那种无聊建议）是，我阐释了从追求好奇心中得出的独特视角。我没有只是反刍别人告诉我的东西，而是重新包装它们以便更好地被理解。我用自己的话把它们写了下来。</p><p>大多数人无法知道，也永远不会知道那些塑造了我的视角的信息，那是从我追求好奇心中获得的。这就是为什么你本身就是一个细分领域。你是一个整合自身经验以帮助他人理解的整合者。</p><p><strong>你必须对你的想法和发现有绝对的信念。</strong></p><p>在所有人都错的时候，你必须是对的。</p><p>你必须无视那些源于缺乏理解的观点。</p><p>如果你在一个已知领域走一条罕见的道路，他们是看不到你所看到的风景的。</p><p>很少有人意识到，你可以通过观察别人道路与自己道路之间的模式，来<em>创造</em>出一条行得通的路径。</p><p>正因为如此，我无法给你提供一个低水平的战术程序来带给你确定性。</p><p>但是，我可以给你一个宏观的指南：</p><ul><li>拉远视角，向理想中的自己请教</li><li>明确你的目标，以此产生愿景和清晰度</li><li>透过这些目标的视角来感知境况，以在其中找到信号</li><li>收集信息，撰写它们，用它们来构建，并借此影响他人</li><li>创造力就是利用你的经验来实现目标</li></ul><p>如果你想精通一个领域，就要去获取元领域（meta domains）的通用知识。</p><p>如果你想精通商业，就去获取关于沟通、价值创造、形而上学、人性、心理学以及任何其他作为价值交换黏合剂的通用知识。</p><p>但是，你必须真刀真枪地去创业，才能消化你从这种追求中获得的知识。</p><p>你不能成天只是学习，却指望着能取得进展。</p><h2 id="整合者-为博学者和自我提升者打造的新职业道路" tabindex="-1">整合者：为博学者和自我提升者打造的新职业道路 <a class="header-anchor" href="#整合者-为博学者和自我提升者打造的新职业道路" aria-label="Permalink to &quot;整合者：为博学者和自我提升者打造的新职业道路&quot;">​</a></h2><p>这条职业道路的前提是你有野心、努力提升自我，并享受跨学科研究。</p><p>它是为那些厌倦了现代工作和商业模式的人准备的。</p><p>你看到大众在工作和生活中缺乏意义。</p><p>你看不到打破默认路径的出路。</p><p>你对目前的走向不满意，但热爱学习和自我教育。</p><p>在 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>，我们帮助人们在90天内将他们的好奇心转化为数字职业。</p><h3 id="什么是整合者" tabindex="-1">什么是整合者 <a class="header-anchor" href="#什么是整合者" aria-label="Permalink to &quot;什么是整合者&quot;">​</a></h3><p>整合者是以好奇心为指南针走上独特道路的人，他们将想法联系起来以实现自己设定的目标，并分发他们的整合成果，以帮助志同道合的人实现类似目标。</p><p>整合者是痴迷的现实探索者。他们明白现实无法被分割成生物、化学、哲学和文学等学校课程。他们明白现实的这些方面已经被记录得很完善了，如果我们想取得更好的成果，就必须把现实看作一个相互联系的整体。整合者为有价值的问题创造整体解决方案。</p><p>整合者是一个<a href="/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people">价值创作者</a>。这是社交媒体上的一类创作者，他们专注于教育和理解，而不是迷因和过度娱乐。</p><p>整合者就像是DJ，只不过混音的是思想。</p><p>整合者是一家去中心化的媒体公司。</p><p>以前人们写书出版的时候，只有极少数人能上电视直播去宣传。</p><p>现在，他们只需要在社交媒体上发发帖子，然后来一轮播客巡回访谈就行了。</p><p>每个人都可以成为自己的媒体公司，靠做自己喜欢的事来谋生。</p><p>作者可以建立受众并在没有出版商的情况下写出一本畅销书。</p><p>音乐人也可以照做，在没有唱片公司的情况下制作一首曲目。</p><p>创意人员同样可以如此，无需成为公司的员工就能销售产品。</p><p>整合者的道路让你有可能做自己喜欢的事（并在做这件事的过程中赚到你想赚的钱）。既然你不依赖“上司”来提供薪水或佣金，你的赚钱潜力就取决于你的技能、受众规模和创造能力。</p><h3 id="整合者的世界观" tabindex="-1">整合者的世界观 <a class="header-anchor" href="#整合者的世界观" aria-label="Permalink to &quot;整合者的世界观&quot;">​</a></h3><p>要成为非本真的自己是很困难的。</p><p>如果你没有综合者的心态、价值观或信念来塑造你自己——你就很难抓住摆在你面前的那些机会。</p><p>你通过学习和实践，逐渐接触并消化新信息来改变自己。这种改变不会一蹴而就。</p><p>你必须抛弃旧观念，当那些婴儿潮一代叫你“找份正经工作”时，你得脸皮厚一点，因为他们根本不知道，这种工作比那些几年后就不复存在的旧工作更安稳、更赚钱。</p><p>当你阅读书籍、消费社交媒体内容以及围绕你的未来展开对话时——尝试将它们与以下综合者的价值观和信念清单联系起来：</p><ul><li>金钱是用来打造你想要但尚未存在之物的工具。</li><li>你生活在一个可以创造自己事业的时代，而不是被分配一份工作。</li><li>在去中心化经济中，个人责任决定了你的人生结果。</li><li>用平庸的目标，你无法得到平庸的结果。用罕见的目标，你才会得到罕见的结果。</li><li>好奇心、探索现实，以及最终对某项手艺的痴迷，是你走向卓越的关键。</li><li>自我教育是你每天必须坚持的基础习惯，无论你学习的主题是什么。</li><li>人类生来就是要扩张、超越和创造的。持续的自我提升和进化不是可选项。如果你作为一个个体停滞不前，你的事业也会如此。</li><li>利用科技和互联网，总有办法打造你想要的任何生活。如果没有办法，那就创造一个。</li></ul><p>通过不断重复和训练你的大脑，你可以将这种世界观化为己有，一旦如此，你想不成功都难。<a href="/letters/you-wont-be-the-same-person-in-6-months-master-anything-fast">你的大脑是一个帮助你实现目标的系统</a>。</p><h3 id="综合者的技能" tabindex="-1">综合者的技能 <a class="header-anchor" href="#综合者的技能" aria-label="Permalink to &quot;综合者的技能&quot;">​</a></h3><blockquote><p>学会销售，学会构建，如果你两样都能做，你将势不可挡。——纳瓦尔 (Naval)</p></blockquote><p>现在，你不能只是“追随你的好奇心”，然后指望一切都会水到渠成。</p><p>那正是你成为挨饿艺术家的原因。</p><p>正如纳瓦尔所说，你必须学会销售，学会构建。</p><p>从宏观上看，这归结为人性（销售）和技术诀窍（构建）。</p><p>由此，我们可以将技能分为3大阵营：</p><p><strong>1) 常青技能</strong></p><p>研究“人性”是一项艰巨的任务。</p><p>它可以经由观察和提问来完成，这应该成为你的习惯，但我们可以让它变得更实用。</p><p>人性可以与运作机制和心理学联系起来。两者的原则都能帮助你理解和预测人类行为。</p><p>人类行为归根结底就是意识到一个问题，设定一个克服它的目标，并制定一个实现目标的计划。这可能是有意识的，也可能是无意识的。许多人的问题和目标都是社会分配的，如果社会是一个行为系统，这就解释了为什么大多数人既安逸又痛苦。</p><p>常青技能包括<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">写作</a>、演讲、营销和销售。</p><p>它们共同代表了互动、沟通和价值交换。</p><p>这些技能是你<em>如何</em>综合想法的边界。</p><p>如果你不懂如何以一种有影响力的方式传播你的想法，你的想法又怎能产生影响？如果你不懂建立受众的技能（沟通和价值交换），你又怎能建立起自己的受众群体？</p><p>去买课程，把你的大脑泡在书籍和播客里，像你的未来全指望它一样去学习常青技能，因为你的未来确实指望它。</p><p><strong>2) 技术技能</strong></p><p>科技的进步已经极大地造福了个人。</p><p>你可以学习编程，这是一条非常可行的道路，但我们也有工具可以让我们无需学习编程就能进行构建。</p><p>过去需要多个员工才能完成的工作，现在只需要一个人加上一些自我教育就能搞定。</p><p>你可以在不到一天的时间里建好一个网站、登陆页或销售漏斗。</p><p>你可以写封电子邮件并立刻发送出去（而不是用小马快递）。</p><p>你可以下载Photoshop，让AI生成令人惊叹的品牌资产。</p><p>构建数字地产已经变得无缝衔接。</p><p>我建议几乎每天都要练习常青技能。</p><p>至于技术技能，我建议在你根据个人兴趣构建项目时边做边学。</p><p>简而言之，你必须学习与建立现代企业相关的所有技术技能。</p><p>平面设计、电子邮件营销、社交媒体内容写作、产品托管以及日程安排软件等服务工具。</p><p>如今这相当简单，但要让它成为你的第二本能还需要一些时间。</p><p><strong>3) 个人兴趣</strong></p><p>你要如何学习这些技能，并确保自己走上一条值得传承给他人的独特道路呢？</p><p>还是那句话，通过追随你的好奇心。</p><p>为了开辟你自己的道路，你必须通过你选择的技术技能来进行写作、演讲、营销和销售。</p><p>个人兴趣为你的项目提供了方向。</p><p>个人兴趣源于意识到你生活中的问题——而不是毫无头脑地把它们扫到地毯下掩盖起来。</p><p>如果我意识到超重正在阻碍我的潜力，我是指真正意识到它是如何蔓延到我生活的方方面面并影响其质量时，我就会自动对健身产生兴趣。</p><p>从那里开始，随着我在该领域进行尝试，我开始对特定的饮食、训练方式和生活方式选择产生兴趣。单单这一点就创造了一条独特的道路。</p><p>现在，如果我想为这种努力增添意义，我就会选择将其变现。因为商业是带着目标去生活的载体。我可以通过把我的成果和教训传授给他人来获得回报，并借助互联网大规模地提升人类的福祉。</p><p>为了做好这件事，健身现在成了我的载体，让我运用常青技能和技术技能来进行构建和销售。</p><h3 id="综合者的习惯" tabindex="-1">综合者的习惯 <a class="header-anchor" href="#综合者的习惯" aria-label="Permalink to &quot;综合者的习惯&quot;">​</a></h3><p>如果你想成为一名综合者，你就必须先做一名综合者。</p><p>这听起来不太合理，所以让我解释一下。</p><p>你没有得到你想要的结果，因为你还不是那个能得到这些结果的人。</p><p>“你是谁”是由你的世界观或视角组成的。</p><p>你的视角影响你对局势的认知（是的，我经常重复这句话，因为这是决定你人生结果的最重要的事情）。</p><p>你对局势的认知决定了你可用的选择，然后在此基础上，你做出有利于实现某个有意识或无意识最终目标的决定。</p><p>随着时间的推移和有意识的练习，这些决定会变成习惯。</p><p>所以，<em>你是谁</em> 就是视角和习惯之间的一场共舞。</p><p>你不可能一夜之间就把我们上面拆解的世界观当成你自己的视角。</p><p>你要在生活中慢慢引入一些习惯，它们会将你推向未知，让你接触到正向反馈，从而强化你试图塑造的身份。</p><p>如果你想成为一名综合者，你就必须采取综合者的生活方式——哪怕是从小规模开始。</p><p>这适用于你在生活中想要的任何东西。它必须体现在你的日常生活中。</p><p>随着时间的推移，当你获得了能让你更进一步的结果时，你就可以增加在这些习惯上花费的时间，让它成为你全职的生活方式。</p><p>你必须先做一名兼职综合者，然后在准备好时再转为全职。</p><p>我们可以将这些习惯浓缩成2个简单的时间块，你可以随着时间和结果的累积来增加它们：</p><p><strong>习惯 1) 生产力时间块</strong></p><p>生产力时间块是用来构建、创造和维护的。</p><p>在这30到90分钟里：</p><ul><li>投入专注的工作</li><li>撰写内容以建立读者群</li><li>打造一款产品为这些读者提供价值</li></ul><p>就是这样。这些就是杠杆。你必须留出时间来构建一个可能盈利并能取代你收入来源的项目。你还必须为该产品获取客户，这样你才能过渡到全职。</p><p>说到这里——全新的 <a href="https://thedankoe.com/planner" target="_blank" rel="noreferrer">FOCI Planner 已经可以订购了</a>。我知道你们很多人都在等一本实体手帐本。</p><p>里面包含了我用来构建专注工作时间块的整套系统：</p><ul><li>为未来创造一个最小可行性愿景</li><li>将其解构为月度、每周和每日目标</li><li>自下而上地设定你的优先任务以实现这些目标</li><li>当你了解自己想要和不想要什么时，迭代你的愿景</li></ul><p>单单这个过程就为习惯2创造了清晰度。</p><p><strong>习惯 2) 创造力时间块</strong></p><p>创造力时间块用于捕捉和连接想法，这些想法可以用于你的创作（也就是 Kortex 应用中的那3个标签页）。</p><p>在这30到90分钟里：</p><ul><li><strong>去散散步。</strong> 远离干扰，利用这段时间去听视频、播客、有声书，或者阅读与你愿景相符的内容。</li><li><strong>捕捉想法。</strong> 要具备创造力，你必须收集那些吸引你注意力的新奇想法，这样你才有东西可以综合到你的写作或构建中。</li><li><strong>沉思。</strong> 休息一下，让你的默认模式网络（Default Mode Network）激活。将你的注意力向内收，让各种想法在你沉思时碰撞交织，将它们联系起来，为你的写作和构建创造出新奇的视角。</li></ul><p>作为一名综合者，生产力和创造力时间块不是可选项。这是你每天必做的两件事。</p><h3 id="综合者的主杠杆" tabindex="-1">综合者的主杠杆 <a class="header-anchor" href="#综合者的主杠杆" aria-label="Permalink to &quot;综合者的主杠杆&quot;">​</a></h3><p>你是一名作家。</p><p>几乎每个人都是。</p><p>你越早意识到并接受这是你身份的一部分，你就能做得越好。</p><p>写作是你进行以下活动的方式：</p><ul><li>发送电子邮件</li><li>撰写内容</li><li>撰写视频脚本</li><li>撰写广告和促销文案</li><li>发送社交私信</li><li>理清你的思路以提升你的表达能力（在短信、对话、视频以及任何其他形式中……写作可以而且应该排在首位）。</li></ul><p>我说的不是技术写作或学术写作。</p><p>我说的是有影响力的写作。</p><p>扎根于说服力、营销、销售、人性和心理学的写作。</p><p>（好的）写作是你将文字转化为价值的方式。</p><p>你不能随时随地、随心所欲地“只是瞎写”。</p><p>你必须基于读者心理的基本要素来展开你的写作：</p><ul><li>迫在眉睫的问题——暗示或明确指出他们想要解决的一个问题。</li><li>渴望的目标——最好是你愿景中的目标，这样你就能吸引和你一样的人（那些你最能帮助到的人）。</li><li>弥合差距的路径——源自个人经验，是你实现该目标的系统。</li></ul><p>我之前在<a href="/letters/value-creation-the-skill-that-built-my-one-person-business">价值创造信件</a>中拆解过这一点。</p><p>写作是你将想法综合成具象之物的方式，这样你才能随着时间的推移不断改进它们。</p><p>没有写作，你的想法就不会变得更好，你的结果也同样如此。</p><p>而且，你也没有在做那件能把你的价值展现在别人面前的事。</p><h3 id="综合者的变现路径" tabindex="-1">综合者的变现路径 <a class="header-anchor" href="#综合者的变现路径" aria-label="Permalink to &quot;综合者的变现路径&quot;">​</a></h3><p>作为一名作家、创作者或综合者，你的变现路径和收入来源是无穷无尽的：</p><ul><li>写一本书</li><li>销售数字产品</li><li>销售实体产品（比如手帐本）</li><li>销售指导、教练服务或咨询服务</li><li>通过写作或任何其他常青/技术技能或个人兴趣做自由职业者</li></ul><p>所有这些路径都是低成本的（实体产品除外），并能让你靠做自己喜欢的事情谋生。</p><p>你可以观察一下创作者经济，就会发现人们凭借几乎任何可以想见的兴趣，通过这些选项赚到了钱（不要陷入信息茧房，认为只有某些特定东西比其他东西更好卖）。</p><p>建立你的读者基本盘，然后打造任何你想要的东西。</p><p>而且一旦你拥有了条件允许的现金流和读者群，你完全可以建立任何你想要的企业，就像我们正在打造 Kortex 那样。</p><p>最后，打个广告。</p><p>如果你想在90天内成为一名综合者，<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">申请成为 Kortex University 为数不多的学生之一吧</a>。</p><p>请留意下一期训练营的开课日期。</p><p>感谢阅读，祝你周末愉快。</p><p>Dan</p><hr><p><a href="/en/letters/the-synthesizer-a-digital-career-path-for-curious-people">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',197))])}const y=l(c,[["render",f]]);export{q as __pageData,y as default};
